                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == col:
                        seen.add((a,b)); q.append((a,b))
            out.append((col, cells))
    return out

def _norm(cells):
    r0 = min(r for r,c in cells); c0 = min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def _variants(shape):
    pts = list(shape)
    forms = set()
    for flip in (1,-1):
        for k in range(4):
            vals=[]
            for r,c in pts:
                if flip == -1: c=-c
                for _ in range(k): r,c=c,-r
                vals.append((r,c))
            r0=min(r for r,c in vals); c0=min(c for r,c in vals)
            forms.add(frozenset((r-r0,c-c0) for r,c in vals))
    return forms

def _inside(child, parent):
    sh = _norm(child)
    variants = _variants(sh)
    r0=min(r for r,c in parent); r1=max(r for r,c in parent)
    c0=min(c for r,c in parent); c1=max(c for r,c in parent)
    for shape in variants:
        hh=max(r for r,c in shape)+1; ww=max(c for r,c in shape)+1
        for a in range(r0,r1-hh+2):
            for b in range(c0,c1-ww+2):
                if all((a+r,b+c) in parent for r,c in shape):
                    # An exact crop: no parent cells outside the selected shape in its box.
                    if all(((a+r,b+c) in parent) == ((r,c) in shape) for r in range(hh) for c in range(ww)):
                        return True
    return False

def transform(grid):
    g=[row[:] for row in grid]
